let msg_id = msg.msg_id

let retry_limit = node.get("retry_limit")
let current_id = node.get("current_id")
let retries = node.get("retries")

// reset if new message
if (current_id || !current_id == msg_id) {
    node.set("current_id", msg_id)
    node.set("retries", 2)
    return [null, msg]
}

// retry until retry limit reached
if (current_id == msg_id) {
    if (retries <= retry_limit) {
        node.set("restries", retries +1)
        return [null, msg]
    } else if (retries > retry_limit) {
        node.set("retries", 0)
        node.set("current_id", "")
        return [msg, null]
    }
}

